def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([2]), fmt([-3]), fmt([-4]), fmt([0]), fmt([3, 5]), fmt([-1, -3]), fmt([7, -1, 4]),
             fmt([1, 1, 1]), fmt([-5, -7, 9]), fmt([3, -3, 0])]
    for n in (2, 3, 4, 5, 6, 8, 10, 12):
        for lo, hi in ((-10, 10), (0, 9), (-9, 0), (1, 20)):
            tests.append(fmt([rng.randint(lo, hi) for _ in range(n)]))
    N = 10 ** 5
    M = 10 ** 9
    tests.append(fmt([rng.randint(-M, M) for _ in range(N)]))
    tests.append(fmt([2 * rng.randint(0, M // 2 - 1) + 1 for _ in range(N)]))
    tests.append(fmt([-(2 * rng.randint(0, M // 2 - 1) + 1) for _ in range(N)]))
    tests.append(fmt([M] * (N - 1) + [-1]))
    return tests

